<?php require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';?><main class="container-fluid py-4 px-lg-4"><h2>Resultados de búsqueda</h2><form class="d-flex mb-4" action="index.php"><input type="hidden" name="c" value="home"><input type="hidden" name="a" value="buscar"><input class="form-control me-2" name="q" value="<?=e($texto)?>" placeholder="¿Qué estás buscando?"><button class="btn btn-primary">Buscar</button></form><?php if($texto===''||!$resultados):?><div class="card vacio"><h5>No se encontró lo buscado</h5><p class="mb-0">Probá con otra palabra o verificá cómo está escrito.</p></div><?php else:?><div class="row g-3"><?php foreach($resultados as $r):?><div class="col-md-6 col-xl-4"><a class="card p-3 text-decoration-none text-dark h-100" href="<?=e($r['url'])?>"><small class="text-primary"><?=e($r['tipo'])?></small><h5><?=e($r['titulo'])?></h5><span class="text-secondary"><?=e($r['detalle'])?></span></a></div><?php endforeach;?></div><?php endif;?></main><?php require __DIR__.'/../footer.php';?>
